#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Sets up the Mac mini to host Nebotok: OrbStack, Tailscale, macOS hardening, then the first
# verified deploy and sharing it on the tailnet. Safe to re-run; it remembers values already saved in .env.
#   scripts/setup-mac-mini.sh             host mode: behind this Mac's own Tailscale (the default)
#   scripts/setup-mac-mini.sh --sidecar   the game as its own Tailscale device (compose.tailscale.yaml)
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Always work on the repo's own .env, wherever the wizard was started from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

# Host mode, the default: the game runs behind this Mac's own Tailscale app. --sidecar sets up the
# optional mode where the game is its own Tailscale device (compose.tailscale.yaml); a re-run keeps
# the mode .env already has.
SIDECAR_FILES=compose.yaml:compose.tailscale.yaml
sidecar=false
case "${1:-}" in
  --sidecar) sidecar=true ;;
  "") [[ "$(_existing COMPOSE_FILE || true)" == *compose.tailscale.yaml* ]] && sidecar=true ;;
  *) printf 'usage: scripts/setup-mac-mini.sh [--sidecar]\n' >&2; exit 2 ;;
esac
if [[ "$sidecar" == true ]]; then TOTAL_STAGES=12; else TOTAL_STAGES=10; fi

POLICY_DOC=deploy/tailscale/policy.md
TS_CONSOLE=https://console.tailscale.com/admin
MAC_TAILSCALE=/Applications/Tailscale.app/Contents/MacOS/Tailscale

# Small checks the wizard runs itself. Each prints what it found and never fails the wizard.
ok_line()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
bad_line() { warn "$1"; SKIPPED+=("$1"); }
# launchd opens the SSH and Screen Sharing ports itself, so ask the port, not the process list.
listening_on() { nc -z -G 1 127.0.0.1 "$1" >/dev/null 2>&1; }
pref() { defaults read /Library/Preferences/com.apple.SoftwareUpdate "$1" 2>/dev/null || echo unset; }
# The Mac's own Tailscale answers, signed in.
mac_tailscale_up() {
  local cli
  cli=$(command -v tailscale 2>/dev/null || echo "$MAC_TAILSCALE")
  [[ -x "$cli" ]] && "$cli" status >/dev/null 2>&1
}

banner "Nebotok on the Mac mini"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "OrbStack is running"
say "Nebotok runs in Docker containers (the game and its backup), and OrbStack is what runs Docker on this Mac."
note "Why it matters for safety: a container sees only the Mac folders that are mounted into it."
note "Nebotok mounts none into the game. The backup container gets one folder, the backup folder."
note "Your files, photos and keys stay out of reach."
if docker info >/dev/null 2>&1; then
  ok_line "Docker answers ($(docker info --format '{{.OperatingSystem}}' 2>/dev/null || echo unknown))."
else
  warn "Docker does not answer. Open OrbStack from Applications, wait for it to start, then continue."
  pause "Press Enter once OrbStack is running"
  docker info >/dev/null 2>&1 && ok_line "Docker answers now." || bad_line "Docker is not running: start OrbStack, then run scripts/update.sh"
fi
step "In OrbStack's Settings, turn on 'Start at login', so the game comes back after a restart."
pause "Press Enter when that is on"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Tailscale: names and HTTPS"
if [[ "$sidecar" == true ]]; then
  say "The iPad will open the game at https://nebotok.<your tailnet>.ts.net."
else
  say "The iPad will open the game at https://<this Mac's name>.<your tailnet>.ts.net:8445, through the"
  say "Tailscale app on this Mac. The game gets no Tailscale device of its own."
  if mac_tailscale_up; then
    ok_line "Tailscale is running and signed in on this Mac."
  else
    warn "Tailscale is not running on this Mac, or not signed in."
    step "Install it from https://tailscale.com/download (or the App Store), open it and sign in."
    pause "Press Enter once Tailscale is signed in"
    mac_tailscale_up && ok_line "Tailscale answers now." || bad_line "Tailscale is not signed in on this Mac: open the Tailscale app and sign in"
  fi
fi
note "Why: MagicDNS gives the game a name, and HTTPS certificates give it a real padlock, which"
note "the iPad needs to install the game as an app. Nothing becomes reachable from the internet."
open_url "$TS_CONSOLE/dns"
step "Under 'MagicDNS', make sure it is enabled."
step "Under 'HTTPS Certificates', select 'Enable HTTPS' and confirm."
pause "Press Enter when both are on"

if [[ "$sidecar" == true ]]; then
# ── 3 (sidecar) ──────────────────────────────────────────────────────────
stage "Tailscale: the access policy"
say "This policy lets family devices open the game, and lets the game reach nothing at all."
note "Why: if the game were ever taken over, it still could not reach this Mac or your other"
note "devices through Tailscale. The full explanation is in $POLICY_DOC."
if command -v pbcopy >/dev/null 2>&1 &&
  awk '/^```hujson$/ {inside = 1; next} /^```$/ && inside {exit} inside' "$POLICY_DOC" | pbcopy; then
  ok_line "Copied the policy to the clipboard."
else
  warn "Could not copy it; open $POLICY_DOC and copy the block under 'The policy'."
fi
open_url "$TS_CONSOLE/acls/file"
step "Select all of the existing policy text and paste over it. The old 'everyone reaches"
step "everyone' rule must not survive: it would let the game reach every device."
step "In the 'tests' section, replace you@example.com with the email you sign in with."
step "Save. If Tailscale reports a failing test, stop and read $POLICY_DOC before changing anything."
pause "Press Enter once the policy is saved without errors"

# ── 4 (sidecar) ──────────────────────────────────────────────────────────
stage "Tailscale: a key for the game"
say "The game's container joins your tailnet once, with a single-use key."
note "Why tagged: the device then belongs to the tailnet, not to you, so only the policy's"
note "game rules apply to it. Why single-use and short-lived: a used key is worthless if it leaks."
open_url "$TS_CONSOLE/settings/keys"
step "Select 'Generate auth key'. Description: nebotok mac mini."
step "Reusable: off.  Expiration: 1 to 7 days.  Ephemeral: off."
step "Pre-approved: on.  Tags: on, and choose tag:nebotok."
step "Select 'Generate key' and keep the page open: it shows the key only once."
pause "Press Enter when you can see the key (tskey-auth-...)"
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Save the settings to .env"
if [[ "$sidecar" == true ]]; then
  say "The key, the device name and the backup folder go into .env, a file only your user account can read."
  note "Why: the key never appears on screen, in the shell history or in git (.env is ignored)."
else
  say "The backup folder goes into .env, a file only your user account can read."
  note "scripts/update.sh adds the verified image's digest to it later. Nothing secret is needed."
fi
if [[ ! -f "$ENV_FILE" ]]; then
  (umask 077 && cp .env.example "$ENV_FILE")
  ok_line "Created $ENV_FILE from .env.example."
fi
chmod 600 "$ENV_FILE"
if [[ "$sidecar" == true ]]; then
  write_env COMPOSE_FILE "$SIDECAR_FILES"
  ask TS_HOSTNAME "Device name for the game (Enter for nebotok):" || TS_HOSTNAME=""
  [[ -n "$TS_HOSTNAME" ]] || TS_HOSTNAME=nebotok
  until [[ "$TS_HOSTNAME" =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$ ]]; do
    warn "Use lowercase letters, digits and dashes only."
    ask TS_HOSTNAME "Device name for the game:" || exit 1
  done
  write_env TS_HOSTNAME "$TS_HOSTNAME"
  ask_secret TS_AUTHKEY "Paste the auth key (hidden):" || exit 1
  until [[ "$TS_AUTHKEY" == tskey-auth-* && "$TS_AUTHKEY" != *REPLACE_ME* ]]; do
    warn "That is not an auth key. It starts with tskey-auth-. Copy it again from the Keys page."
    ask_secret TS_AUTHKEY "Paste the auth key (hidden):" || exit 1
  done
  write_env TS_AUTHKEY "$TS_AUTHKEY"
  unset TS_AUTHKEY
fi
say "Backups go to a folder on this Mac. In your home folder, Time Machine copies them as well."
ask BACKUP_DIR "Backup folder (Enter for $HOME/NebotokBackups):" || BACKUP_DIR=""
[[ -n "$BACKUP_DIR" && "$BACKUP_DIR" != *REPLACE_ME* ]] || BACKUP_DIR="$HOME/NebotokBackups"
BACKUP_DIR=${BACKUP_DIR/#\~/$HOME}
until [[ "$BACKUP_DIR" == /* && "$BACKUP_DIR" != *[\'\"\$\`\\]* ]] && mkdir -p "$BACKUP_DIR" 2>/dev/null; do
  warn "Give a full path that starts with / and has no quotes, e.g. $HOME/NebotokBackups."
  ask BACKUP_DIR "Backup folder:" || exit 1
done
chmod 700 "$BACKUP_DIR"
write_env BACKUP_DIR "$BACKUP_DIR"
ok_line "$BACKUP_DIR is there and readable by you only."
note "Litestream keeps a copy of the saves there seconds behind the game, plus 30 nightly snapshots."
perms=$(stat -f '%Lp' "$ENV_FILE" 2>/dev/null || stat -c '%a' "$ENV_FILE")
[[ "$perms" == 600 ]] && ok_line "$ENV_FILE is readable by you only (mode 600)." || bad_line "$ENV_FILE has mode $perms; run: chmod 600 .env"
[[ "$sidecar" == true ]] && note "You can close the Keys page now."
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "macOS: security updates and firewall"
say "Automatic security updates and the firewall keep the Mac itself patched and closed."
note "Why: the containers are only as safe as the Mac they run on."
open_url "x-apple.systempreferences:com.apple.Software-Update-Settings.extension"
step "Software Update: select the (i) next to 'Automatic updates' and turn on at least"
step "'Install Security Responses and system files' and 'Download new updates when available'."
pause "Press Enter when that is set"
open_url "x-apple.systempreferences:com.apple.Network-Settings.extension"
step "Network > Firewall: turn it on. (If the page did not open: System Settings > Network > Firewall.)"
pause "Press Enter when the firewall is on"
# An unset key means the macOS default, which is on; only an explicit 0 means someone turned it off.
critical=$(pref CriticalUpdateInstall)
[[ "$critical" != 0 ]] && ok_line "Security responses install automatically ($critical)." || bad_line "Automatic security responses are off: System Settings > General > Software Update"
firewall=$(/usr/libexec/ApplicationFirewall/socketfilterfw --getglobalstate 2>/dev/null || true)
[[ "$firewall" == *"State = 1"* || "$firewall" == *"State = 2"* ]] && ok_line "Firewall: on." || bad_line "The macOS firewall looks off: System Settings > Network > Firewall"
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "macOS: remote access off"
say "Remote Login (SSH) and Screen Sharing let other computers control this Mac."
note "Why: switched off, there is no door to guess a password at. Leave one on only if you use it."
open_url "x-apple.systempreferences:com.apple.Sharing-Settings.extension"
step "General > Sharing: turn off Remote Login and Screen Sharing (and Remote Management),"
step "unless you know you need them."
pause "Press Enter when done"
listening_on 22 && warn "Something is listening on port 22 (SSH). Fine only if you meant to keep Remote Login." || ok_line "Remote Login (port 22) is off."
listening_on 5900 && warn "Something is listening on port 5900 (Screen Sharing). Fine only if you meant to keep it." || ok_line "Screen Sharing (port 5900) is off."
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "macOS: always on"
say "The game is only up while the Mac is awake, so it should never sleep and should start"
say "again by itself after a power cut."
note "These need your admin password, so run them yourself in another Terminal window:"
printf '\n    %ssudo pmset -a sleep 0%s\n' "$BOLD" "$RESET"
printf '    %ssudo pmset -a autorestart 1%s\n\n' "$BOLD" "$RESET"
note "(The display may still sleep; that does not matter.)"
pause "Press Enter after running both"
sleep_now=$(pmset -g 2>/dev/null | awk '$1 == "sleep" {print $2}')
restart_now=$(pmset -g 2>/dev/null | awk '$1 == "autorestart" {print $2}')
[[ "$sleep_now" == 0 ]] && ok_line "System sleep: never." || bad_line "System sleep is ${sleep_now:-unknown}: run sudo pmset -a sleep 0"
[[ "$restart_now" == 1 ]] && ok_line "Restart after power failure: on." || bad_line "Restart after power failure is ${restart_now:-unknown}: run sudo pmset -a autorestart 1"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "macOS: FileVault stays on"
say "FileVault encrypts the disk, so a stolen Mac mini gives away nothing."
note "The cost: after a power cut the Mac restarts to a login screen and waits for your"
note "password before the game comes back. That is rare, and the safer choice."
note "After logging in, OrbStack (start at login) brings the containers back by itself."
vault=$(fdesetup status 2>/dev/null || true)
[[ "$vault" == *"is On"* ]] && ok_line "FileVault is on." || bad_line "FileVault is not on: System Settings > Privacy & Security > FileVault"
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "GitHub: the game image"
say "The Mac mini runs only images built by the repo's own GitHub Actions, and checks GitHub's"
say "signed record of each build before running it. That needs two things:"
step "The image must be public, so the Mac can download it without a password."
step "The GitHub CLI must be signed in, to fetch the signed build record."
if gh auth status >/dev/null 2>&1; then ok_line "GitHub CLI is signed in."; else bad_line "GitHub CLI is not signed in: run gh auth login"; fi
if docker buildx imagetools inspect ghcr.io/nazuje/nebotok:main >/dev/null 2>&1; then
  ok_line "ghcr.io/nazuje/nebotok:main is published and readable."
else
  warn "Could not read ghcr.io/nazuje/nebotok:main yet."
  note "If CI has not run on main yet, push first and wait for the 'image' job to finish."
  note "If it has, make the package public:"
  open_url "https://github.com/users/nazuje/packages/container/nebotok/settings"
  step "Danger Zone > Change visibility > Public."
  pause "Press Enter when done"
  docker buildx imagetools inspect ghcr.io/nazuje/nebotok:main >/dev/null 2>&1 &&
    ok_line "The image is readable now." || bad_line "ghcr.io/nazuje/nebotok:main is not readable yet"
fi
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Start the game"
if [[ "$sidecar" == true ]]; then
  say "scripts/update.sh checks the newest image's build record, then starts the game, Tailscale and the backup."
else
  say "scripts/update.sh checks the newest image's build record, then starts the game and the backup."
fi
note "It refuses to run any image that GitHub Actions in nazuje/nebotok did not build from main."
if confirm "Run scripts/update.sh now?"; then
  if scripts/update.sh; then
    ok_line "Nebotok is running."
  else
    bad_line "scripts/update.sh did not finish: read its message, fix it, and run it again"
  fi
else
  SKIPPED+=("start the game: scripts/update.sh")
fi
pause

# ── 12 (sidecar) / 10 (host) ─────────────────────────────────────────────
if [[ "$sidecar" == true ]]; then
  stage "Open it on the iPad"
  say "Find the game's address in the Tailscale admin console:"
  open_url "$TS_CONSOLE/machines"
  step "Find the '$TS_HOSTNAME' device with the tag:nebotok label and open it."
  step "Its full name ends in .ts.net. The game is at https:// followed by that name."
  fqdn=$(docker compose exec -T ts tailscale --socket=/tmp/tailscaled.sock status --json 2>/dev/null |
    awk -F'"' '/"DNSName"/ {print $4; exit}' | sed 's/\.$//' || true)
  [[ -n "$fqdn" ]] && ok_line "This Mac says it is: https://$fqdn"
else
  stage "Share it on your tailnet and open it on the iPad"
  say "scripts/serve.sh tells this Mac's Tailscale to share the game on HTTPS port 8445."
  note "It changes nothing else: other services this Mac already shares keep their ports."
  note "Who can open it: every device your tailnet's access policy lets reach this Mac."
  if scripts/serve.sh; then
    ok_line "The game is shared. Its address is the https://...:8445 line above."
  else
    bad_line "scripts/serve.sh did not finish: read its message, then run it again"
  fi
fi
say "On the iPad:"
step "Install the Tailscale app and sign in with a family account."
step "Open that https address in Safari. Do not open it on this Mac: the game plays sound."
step "Share > Add to Home Screen, so the children can start it with one tap."
